/**
 * SVG markup for a preset id, or null when the id has no art.
 * Callers fall back to the gray person, so an unknown id is not a broken image.
 *
 * The same preset is rendered twice on the profile page - once in the main circle
 * and once as the selected picker option - so any internal ids are suffixed per
 * call. Without that the two copies would put the same id in the document twice.
 *
 * @param {string} id
 * @returns {string|null}
 */
export function avatarArt(id) {
  const art = ART[id];
  if (!art) return null;
  if (!art.includes('id="')) return art;

  const suffix = `-${++renderCount}`;
  return art
    .replace(/\bid="([^"]+)"/g, (_, name) => `id="${name}${suffix}"`)
    .replace(/url\(#([^)]+)\)/g, (_, name) => `url(#${name}${suffix})`);
}
